export default function ImpactCalculator({ locale = "en" }: { locale?: Locale }) {
  if (locale === "en") return <ImpactConsoleDashboard />;
  return <LegacyImpactCalculator locale={locale} />;
}

type DashboardResult = { investment: number; total: number; ratio: number; adjustment: number; values: { social: number; environmental: number; economic: number } };

function dashboardResult(form: FormState): DashboardResult {
  const investment = form.budget + form.volunteerHours * form.hourlyRate;
  const change = Math.max(0, Math.min(100, form.changeRate)) / 100;
  const adjustment = (1 - form.deadweight / 100) * (1 - form.attribution / 100) * (1 - form.displacement / 100) * (1 - form.dropoff / 100);
  const values = { social: form.beneficiaries * form.socialProxy * change * adjustment, environmental: form.waste * form.environmentalProxy * change * adjustment, economic: form.jobs * form.economicProxy * change * adjustment };
  const total = values.social + values.environmental + values.economic;
  return { investment, total, values, adjustment, ratio: investment > 0 ? total / investment : 0 };
}

function compactMoney(value: number) { return value >= 1000000 ? `${(value / 1000000).toFixed(1)}M` : value >= 1000 ? `${(value / 1000).toFixed(0)}K` : money(value, "en"); }
function DashboardKpi({ icon, label, value, detail, accent = "" }: { icon: React.ReactNode; label: string; value: string; detail: string; accent?: string }) { return <div className={`impact-kpi glass-panel ${accent}`}><i>{icon}</i><span>{label}</span><strong>{value}</strong><small>{detail}</small></div>; }
function DashboardBar({ label, value, total, color }: { label: string; value: number; total: number; color: string }) { const width = total ? Math.max(4, value / total * 100) : 4; return <div className="dashboard-bar"><div><span><i className={`dashboard-dot ${color}`} />{label}</span><b>{Math.round(width)}%</b></div><span><i className={color} style={{ width: `${width}%` }} /></span></div>; }
function DashboardField({ label, help, value, update, prefix, suffix, range }: { label: string; help: string; value: number; update: (value: string) => void; prefix?: string; suffix?: string; range?: boolean }) { return <label className="dashboard-field"><b>{label}</b><small>{help}</small><span>{prefix && <i>{prefix}</i>}<input type="number" min="0" max={range ? 100 : undefined} value={value} onChange={(event) => update(event.target.value)} />{suffix && <i>{suffix}</i>}</span>{range && <input className="dashboard-range" type="range" min="0" max="100" value={value} onChange={(event) => update(event.target.value)} />}</label>; }
function DashboardDimension({ label, value, total, color }: { label: string; value: number; total: number; color: string }) { return <div className="dashboard-dimension"><span><i className={`dashboard-dot ${color}`} />{label}</span><strong>${compactMoney(value)}</strong><small>{total ? Math.round(value / total * 100) : 0}%</small></div>; }
function DashboardWaterfall({ result }: { result: DashboardResult }) { const gross = result.total / Math.max(result.adjustment, .01); return <div className="dashboard-waterfall glass-panel"><span>VALUE BRIDGE</span><h3>From gross outcomes to net value</h3><div>{[["Gross outcomes", gross, "mint"], ["Adjustments", gross - result.total, "coral"], ["Net value", result.total, "gold"]].map(([label, value, color]) => <section key={String(label)}><b>${compactMoney(Number(value))}</b><i className={String(color)} style={{ height: `${Math.max(14, Math.min(100, Number(value) / Math.max(gross, 1) * 100))}%` }} /><small>{label}</small></section>)}</div></div>; }
function DashboardScenario({ form, result }: { form: FormState; result: DashboardResult }) { const scenarios = [{ label: "Conservative", ratio: dashboardResult({ ...form, changeRate: Math.max(20, form.changeRate - 20), deadweight: Math.min(90, form.deadweight + 10) }).ratio, color: "coral" }, { label: "Expected", ratio: result.ratio, color: "mint" }, { label: "Optimistic", ratio: dashboardResult({ ...form, changeRate: Math.min(100, form.changeRate + 15), deadweight: Math.max(0, form.deadweight - 8) }).ratio, color: "gold" }]; const max = Math.max(...scenarios.map((item) => item.ratio), 1); return <section className="dashboard-scenario glass-panel"><div><span>DECISION LENS</span><h2>Scenario analysis</h2><p>See how the SROI ratio responds to different assumptions. This is a sensitivity lens, not a forecast.</p><small><SlidersHorizontal size={14} /> Most sensitive input: <b>{form.changeRate >= form.deadweight ? "Positive change rate" : "Deadweight"}</b></small></div><aside>{scenarios.map((item) => <section key={item.label}><b>{item.ratio.toFixed(2)} : 1</b><i className={item.color} style={{ height: `${Math.max(12, item.ratio / max * 100)}%` }} /><small>{item.label}</small></section>)}</aside></section>; }

function ImpactDashboard() {
  const [stage, setStage] = useState(0);
  const [form, setForm] = useState<FormState>(initialForm);
  const result = useMemo(() => dashboardResult(form), [form]);
  const update = (key: keyof FormState, value: string) => setForm((current) => ({ ...current, [key]: parseNumber(value) }));
  const stages = ["Overview", "Financial inputs", "Direct outputs", "Outcomes & values", "Adjustments", "Results"];
  const complete = Math.round(Object.values(form).filter((value) => value > 0).length / Object.keys(form).length * 100);
  const exportPdf = () => { const document = new jsPDF(); document.setFontSize(20); document.text("Social Impact Assessment Report", 20, 24); document.setFontSize(11); document.text(`SROI ratio: ${result.ratio.toFixed(2)} : 1`, 20, 40); document.text(`Net social value: $${money(result.total, "en")}`, 20, 50); document.text(`Total investment: $${money(result.investment, "en")}`, 20, 60); document.save("social-impact-assessment.pdf"); };
  const field = (key: keyof FormState, label: string, help: string, prefix?: string, suffix?: string, range = false) => <DashboardField label={label} help={help} value={form[key]} update={(value) => update(key, value)} prefix={prefix} suffix={suffix} range={range} />;
  return <main className="impact-dashboard" dir="ltr"><style>{dashboardStyles + dashboardGlassOverrides}</style><div className="impact-dashboard-inner">
    <nav className="dashboard-nav"><Link href="/en" className="dashboard-brand"><span><Sparkles size={15} /></span><b>SSE<small>IMPACT LAB</small></b></Link><div className="dashboard-status"><i /> Assessment in progress <em>•</em> Updated just now</div><div className="dashboard-nav-actions"><button type="button" aria-label="Save assessment"><Save size={16} /></button><Link href="/en"><ArrowLeft size={15} /> Back to encyclopedia</Link></div></nav>
    <header className="dashboard-hero"><div><span className="dashboard-eyebrow">DECISION SUPPORT FOR PURPOSE-LED ORGANIZATIONS</span><h1>Social impact<br /><em>assessment</em></h1><p>Turn your programme assumptions into a transparent first estimate of social, environmental and economic value.</p></div><div className="dashboard-note glass-panel"><ShieldCheck size={20} /><span><b>Evidence-aware by design</b>Keep assumptions visible, then review this screening estimate with local evidence before making decisions.</span></div></header>
    <section className="dashboard-kpis"><DashboardKpi icon={<WalletCards size={17} />} label="Total investment" value={`$${money(result.investment)}`} detail="Cash + volunteer value" /><DashboardKpi icon={<TrendingUp size={17} />} label="Net social value" value={`$${money(result.total)}`} detail="After adjustments" accent="mint" /><DashboardKpi icon={<Sparkles size={17} />} label="SROI ratio" value={`${result.ratio.toFixed(2)} : 1`} detail="Value created per $1" accent="gold" /><DashboardKpi icon={<ShieldCheck size={17} />} label="Data confidence" value="Medium" detail={`${complete}% of fields complete`} accent="blue" /></section>
    <div className="dashboard-grid"><aside className="dashboard-sidebar glass-panel"><span className="sidebar-label">WORKSPACE <b>{complete}% complete</b></span><div className="dashboard-progress"><i style={{ width: `${complete}%` }} /></div>{stages.map((label, index) => <button key={label} type="button" className={`${stage === index ? "active" : ""} ${index < stage ? "done" : ""}`} onClick={() => setStage(index)}><strong>{index < stage ? "✓" : `0${index + 1}`}</strong><span><b>{label}</b><small>{index < stage ? "Completed" : index === stage ? "Current step" : "Not started"}</small></span><ArrowRight size={13} /></button>)}<div className="sidebar-help"><CircleHelp size={15} /><span><b>Data tip</b>Start with measured data, then use proxies only where direct evidence is unavailable.</span></div></aside>
      <section className="dashboard-workspace glass-panel"><div className="workspace-label">ASSESSMENT / {String(stage + 1).padStart(2, "0")} <b>{stages[stage]}</b></div><div className="workspace-body">{stage === 0 && <><div className="dashboard-section-head"><div><span>AT A GLANCE</span><h2>Assessment overview</h2><p>Your assumptions become a live estimate. Refine any input to see the result change instantly.</p></div><button type="button" onClick={() => setStage(1)}>Refine inputs <ArrowRight size={15} /></button></div><div className="overview-panels"><div className="dashboard-chart glass-panel"><span>VALUE MIX</span><h3>Contribution by dimension</h3><div className="overview-chart-content"><div className="dashboard-donut" style={{ background: `conic-gradient(#58d7bd 0deg ${result.total ? result.values.social / result.total * 360 : 120}deg,#f1c66f ${result.total ? result.values.social / result.total * 360 : 120}deg ${result.total ? (result.values.social + result.values.economic) / result.total * 360 : 240}deg,#76bfe3 0 360deg)` }}><span><b>${compactMoney(result.total)}</b>net value</span></div><div><DashboardBar label="Social" value={result.values.social} total={result.total} color="mint" /><DashboardBar label="Economic" value={result.values.economic} total={result.total} color="gold" /><DashboardBar label="Environmental" value={result.values.environmental} total={result.total} color="blue" /></div></div></div><div className="dashboard-output glass-panel"><span>DIRECT REACH</span><h3>What the programme delivers</h3><p><Users /> <b>{money(form.beneficiaries)}</b> people reached</p><p><BriefcaseBusiness /> <b>{money(form.jobs)}</b> jobs created</p><p><Recycle /> <b>{money(form.waste)} kg</b> waste recovered</p></div></div><DashboardWaterfall result={result} /></>}{stage === 1 && <DashboardStep title="Financial inputs" description="Start with the resources committed directly to the programme. Use the same currency throughout this assessment."><>{field("budget", "Annual budget / initial investment", "Direct cash committed to this programme.", "$", "USD")}{field("volunteerHours", "Volunteer hours", "Unpaid time contributed during the assessment period.", undefined, "hours")}{field("hourlyRate", "Base hourly rate", "A conservative value for one volunteer hour.", "$", "/ hour")}</></DashboardStep>}{stage === 2 && <DashboardStep title="Direct outputs" description="Describe the immediate reach of the work. Count people and jobs directly connected to this intervention."><>{field("beneficiaries", "Direct beneficiaries", "People directly reached, trained or supported.", undefined, "people")}{field("jobs", "Sustainable jobs created", "New jobs expected to remain in place for a meaningful period.", undefined, "jobs")}{field("waste", "Waste diverted", "Material recovered through the intervention.", undefined, "kg")}</></DashboardStep>}{stage === 3 && <DashboardStep title="Outcomes & values" description="Enter the estimated value of each outcome and the share of positive change linked to your intervention."><>{field("changeRate", "Positive change rate", "Measured or evidenced estimate of change.", undefined, "%", true)}{field("socialProxy", "Social value per beneficiary", "For example, avoided health or welfare costs.", "$", "per person")}{field("environmentalProxy", "Environmental value per kg", "Collection cost avoided plus stored carbon value.", "$", "per kg")}{field("economicProxy", "Economic value per job", "Estimated public and household value of stable work.", "$", "per job")}</></DashboardStep>}{stage === 4 && <DashboardStep title="Adjustments" description="Reduce overclaiming by asking what would have happened anyway, what belongs to others and how value changes over time."><>{field("deadweight", "Deadweight", "Change likely without your intervention.", undefined, "%", true)}{field("attribution", "Attribution", "Success attributable to other organizations.", undefined, "%", true)}{field("displacement", "Displacement", "Positive value that creates harm elsewhere.", undefined, "%", true)}{field("dropoff", "Drop-off", "Annual reduction in outcome value over time.", undefined, "%", true)}</></DashboardStep>}{stage === 5 && <DashboardStep title="Assessment result" description="Review the live estimate, then download a report with the assumptions used in this screening calculation."><div className="dashboard-result-cards"><span>NET SOCIAL VALUE<strong>${money(result.total)}</strong></span><span>TOTAL INVESTMENT<strong>${money(result.investment)}</strong></span><span>SROI RATIO<strong>{result.ratio.toFixed(2)} : 1</strong></span></div><DashboardWaterfall result={result} /></DashboardStep>}</div>{stage > 0 && stage < 5 && <div className="workspace-actions"><button type="button" onClick={() => setStage(stage - 1)}><ArrowLeft size={15} /> Previous</button><button type="button" className="primary" onClick={() => setStage(stage + 1)}>Continue <ArrowRight size={15} /></button></div>}</section>
      <aside className="dashboard-result glass-panel"><span className="result-live">LIVE RESULT <i /></span><small>SROI ratio</small><strong className="result-number">{result.ratio.toFixed(2)}<em>: 1</em></strong><p>Every $1 invested creates an estimated <b>${result.ratio.toFixed(2)}</b> in social value.</p><div className="result-donut" style={{ background: `conic-gradient(#58d7bd 0 ${result.total ? result.values.social / result.total * 360 : 120}deg,#f1c66f 0 240deg,#76bfe3 0 360deg)` }}><span><b>${compactMoney(result.total)}</b>net value</span></div><DashboardDimension label="Social" value={result.values.social} total={result.total} color="mint" /><DashboardDimension label="Economic" value={result.values.economic} total={result.total} color="gold" /><DashboardDimension label="Environmental" value={result.values.environmental} total={result.total} color="blue" /><button className="dashboard-download" type="button" onClick={exportPdf}><Download size={15} /> Download report</button><small className="result-disclaimer"><ShieldCheck size={14} /> Screening estimate, not an audited valuation.</small></aside></div>
    <DashboardScenario form={form} result={result} /><footer className="dashboard-footer"><span>Impact Lab / assessment workspace</span><button type="button" onClick={() => { setForm(initialForm); setStage(0); }}><RotateCcw size={13} /> Reset assessment</button><Link href="/en/case-studies">Explore case studies <ArrowRight size={13} /></Link></footer>
  </div></main>;
}

