function LegacyImpactCalculator({ locale = "en" }: { locale?: Locale }) {
  const isPersian = locale === "fa";
  const copy = getCopy(isPersian);
  const steps = [copy.overview, copy.inputs, copy.outputs, copy.outcomes, copy.adjustments, copy.results];
  const [step, setStep] = useState(0);
  const [form, setForm] = useState<FormState>(isPersian ? persianInitialForm : initialForm);
  const update = (key: keyof FormState, value: string) => setForm((current) => ({ ...current, [key]: parseNumber(value) }));
  const result = useMemo(() => {
    const investment = form.budget + form.volunteerHours * form.hourlyRate;
    const change = Math.max(0, Math.min(100, form.changeRate)) / 100;
    const adjustment = (1 - form.deadweight / 100) * (1 - form.attribution / 100) * (1 - form.displacement / 100) * (1 - form.dropoff / 100);
    const values = { social: form.beneficiaries * form.socialProxy * change * adjustment, environmental: form.waste * form.environmentalProxy * change * adjustment, economic: form.jobs * form.economicProxy * change * adjustment };
    const total = values.social + values.environmental + values.economic;
    return { investment, values, total, ratio: investment > 0 ? total / investment : 0 };
  }, [form]);
  const exportPdf = () => {
    const document = new jsPDF();
    document.setFontSize(20);
    document.text("Social Impact Assessment Report", 20, 24);
    document.setFontSize(11);
    document.text(`SROI ratio: ${result.ratio.toFixed(2)} : 1`, 20, 40);
    document.text(`Net social value: ${money(result.total, locale)}`, 20, 50);
    document.text(`Total investment: ${money(result.investment, locale)}`, 20, 60);
    document.save(isPersian ? "گزارش-ارزیابی-اثر-اجتماعی.pdf" : "social-impact-assessment.pdf");
  };
  const activeTitle = [copy.overviewTitle, copy.financialTitle, copy.outputTitle, copy.outcomeTitle, copy.adjustmentTitle, copy.resultTitle][step];
  const activeText = [copy.overviewText, copy.financialText, copy.outputText, copy.outcomeText, copy.adjustmentText, copy.resultText][step];

  return <main className="impact-page" dir={isPersian ? "rtl" : "ltr"}><style>{`
    .impact-page{--ink:#172329;--muted:#68787a;--paper:#fffefa;--line:#d6e2df;--green:#176b5b;--lime:#b9d946;--orange:#e77745;min-height:100vh;padding:30px clamp(16px,5vw,72px) 70px;color:var(--ink);background:linear-gradient(135deg,#eef6f2,#fbf1e5);font-family:"Vazirmatn",Tahoma,Arial,sans-serif}.impact-shell{max-width:1220px;margin:0 auto}.impact-nav{display:flex;justify-content:space-between;gap:16px;margin-bottom:38px}.impact-nav a,.impact-footer a{color:var(--green);font-weight:800;text-decoration:none}.impact-heading{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(280px,.9fr);gap:18px;margin-bottom:18px;align-items:end}.impact-kicker{color:var(--orange);font-size:12px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.impact-heading h1{max-width:100%;margin:10px 0 14px;font-size:clamp(40px,6vw,78px);line-height:.98}.impact-heading p{max-width:100%;margin:0;color:var(--muted);font-size:17px;line-height:1.65}.impact-note{padding:20px;border-top:5px solid var(--lime);background:rgba(255,254,250,.76);line-height:1.7}.impact-note strong{display:block;margin-bottom:6px;color:var(--green);font-size:22px}.impact-layout{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(280px,.9fr);gap:18px;align-items:start}.impact-panel{min-width:0;border:1px solid var(--line);background:rgba(255,254,250,.9);box-shadow:0 18px 40px rgba(26,70,60,.08)}.impact-workspace-heading{padding:20px 28px 0;color:var(--green);font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.impact-progress{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));min-height:76px;border-bottom:1px solid var(--line)}.impact-progress button{min-width:0;padding:13px 7px;border:0;border-bottom:3px solid transparent;color:var(--muted);background:transparent;cursor:pointer;font:inherit;font-size:12px;line-height:1.25}.impact-progress button.active{border-bottom-color:var(--orange);color:var(--green);font-weight:800}.impact-form{min-height:555px;padding:28px}.impact-form h2{margin:0 0 8px;font-size:28px}.impact-form>p{margin:0 0 24px;color:var(--muted);line-height:1.7}.impact-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.impact-field{display:grid;align-content:start;gap:7px}.impact-field>span{font-weight:800;font-size:13px}.impact-field small{min-height:38px;color:var(--muted);line-height:1.45}.impact-field input{box-sizing:border-box;width:100%;min-height:46px;padding:0 12px;border:1px solid var(--line);background:#fff;color:var(--ink);font:inherit}.impact-field input:focus{outline:3px solid rgba(23,107,91,.16);border-color:var(--green)}.impact-actions{display:flex;justify-content:space-between;gap:12px;margin-top:28px}.impact-button{padding:11px 16px;border:1px solid var(--green);color:var(--green);background:#fff;cursor:pointer;font:inherit;font-weight:800}.impact-button.primary{color:#fff;background:var(--green)}.impact-result{min-width:0;padding:28px;background:var(--green);color:#fff}.impact-result h2{margin:0 0 6px;font-size:19px}.impact-result>p{margin:0;color:rgba(255,255,255,.78);font-size:13px;line-height:1.6}.impact-ratio{margin:24px 0;padding:18px 0;border-top:1px solid rgba(255,255,255,.2);border-bottom:1px solid rgba(255,255,255,.2)}.impact-ratio strong{display:block;color:var(--lime);font-size:48px;line-height:1.1}.impact-ratio span{font-size:13px}.impact-bars{display:grid;gap:18px}.impact-bar-row{display:grid;gap:6px}.impact-bar-label{display:flex;justify-content:space-between;gap:10px;font-size:13px}.impact-bar-label span{min-width:0}.impact-bar-label strong{white-space:nowrap}.impact-bar{height:9px;background:rgba(255,255,255,.17)}.impact-bar span{display:block;height:100%;background:var(--lime)}.impact-result .impact-button{width:100%;margin-top:26px;border-color:#fff}.impact-footer{display:flex;justify-content:space-between;gap:16px;margin-top:32px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}@media(max-width:850px){.impact-heading,.impact-layout{grid-template-columns:1fr}.impact-form{min-height:0}.impact-result{order:-1}}@media(max-width:600px){.impact-page{padding:20px 14px 48px}.impact-fields{grid-template-columns:1fr}.impact-progress{min-height:92px}.impact-progress button{font-size:10px;padding-inline:3px}.impact-form{padding:20px}.impact-heading h1{font-size:52px}.impact-footer{flex-direction:column}}
  `}</style><div className="impact-shell">
    <nav className="impact-nav"><Link href={isPersian ? "/fa" : "/en"}>{copy.brand}</Link><Link href={isPersian ? "/fa" : "/en"}>{copy.back}</Link></nav>
    <header className="impact-heading"><div><div className="impact-kicker">{copy.kicker}</div><h1>{copy.title}</h1><p>{copy.intro}</p></div><div className="impact-note"><strong>{copy.designed}</strong><span>{copy.note}</span></div></header>
    <div className="impact-layout"><section className="impact-panel"><div className="impact-workspace-heading">{copy.workspace}</div><nav className="impact-progress" aria-label={copy.workspace}>{steps.map((label, index) => <button key={label} className={step === index ? "active" : ""} type="button" onClick={() => setStep(index)} aria-current={step === index ? "step" : undefined}>{numberText(index + 1, locale)}. {label}</button>)}</nav><div className="impact-form"><h2>{activeTitle}</h2><p>{activeText}</p>{step === 0 && <Overview copy={copy} result={result} locale={locale} />}{step === 1 && <div className="impact-fields"><Field locale={locale} label={copy.investment} help={copy.investmentHelp} value={form.budget} onChange={(value) => update("budget", value)} /><Field locale={locale} label={copy.volunteer} help={copy.volunteerHelp} value={form.volunteerHours} onChange={(value) => update("volunteerHours", value)} /><Field locale={locale} label={copy.hourly} help={copy.hourlyHelp} value={form.hourlyRate} onChange={(value) => update("hourlyRate", value)} /></div>}{step === 2 && <div className="impact-fields"><Field locale={locale} label={copy.beneficiaries} help={copy.beneficiariesHelp} value={form.beneficiaries} onChange={(value) => update("beneficiaries", value)} /><Field locale={locale} label={copy.jobs} help={copy.jobsHelp} value={form.jobs} onChange={(value) => update("jobs", value)} /><Field locale={locale} label={copy.waste} help={copy.wasteHelp} value={form.waste} onChange={(value) => update("waste", value)} /></div>}{step === 3 && <div className="impact-fields"><Field locale={locale} label={copy.change} help={copy.changeHelp} value={form.changeRate} onChange={(value) => update("changeRate", value)} /><Field locale={locale} label={copy.socialProxy} help={copy.socialProxyHelp} value={form.socialProxy} onChange={(value) => update("socialProxy", value)} /><Field locale={locale} label={copy.environmentalProxy} help={copy.environmentalProxyHelp} value={form.environmentalProxy} onChange={(value) => update("environmentalProxy", value)} /><Field locale={locale} label={copy.economicProxy} help={copy.economicProxyHelp} value={form.economicProxy} onChange={(value) => update("economicProxy", value)} /></div>}{step === 4 && <div className="impact-fields"><Field locale={locale} label={copy.deadweight} help={copy.deadweightHelp} value={form.deadweight} onChange={(value) => update("deadweight", value)} /><Field locale={locale} label={copy.attribution} help={copy.attributionHelp} value={form.attribution} onChange={(value) => update("attribution", value)} /><Field locale={locale} label={copy.displacement} help={copy.displacementHelp} value={form.displacement} onChange={(value) => update("displacement", value)} /><Field locale={locale} label={copy.dropoff} help={copy.dropoffHelp} value={form.dropoff} onChange={(value) => update("dropoff", value)} /></div>}{step === 5 && <Overview copy={copy} result={result} locale={locale} />}{step > 0 && <div className="impact-actions"><button className="impact-button" type="button" onClick={() => setStep((current) => Math.max(0, current - 1))}>{copy.previous}</button><button className="impact-button primary" type="button" onClick={() => setStep((current) => Math.min(5, current + 1))}>{step === 5 ? copy.review : copy.next}</button></div>}</div></section><aside className="impact-result" aria-live="polite"><h2>{copy.resultTitle}</h2><p>{copy.resultText}</p><div className="impact-ratio"><strong>{numberText(Number(result.ratio.toFixed(2)), locale)} : 1</strong><span>{copy.ratio}</span></div><div className="impact-bars"><ImpactBar locale={locale} label={copy.social} value={result.values.social} total={result.total} /><ImpactBar locale={locale} label={copy.environmental} value={result.values.environmental} total={result.total} /><ImpactBar locale={locale} label={copy.economic} value={result.values.economic} total={result.total} /></div><button className="impact-button" type="button" onClick={exportPdf}>{copy.download}</button></aside></div>
    <footer className="impact-footer"><span>{copy.footer}</span><Link href={isPersian ? "/fa/case-studies" : "/en/case-studies"}>{copy.cases} {isPersian ? "←" : "→"}</Link></footer>
  </div></main>;
}

function Field({ locale, label, help, value, onChange }: { locale: Locale; label: string; help: string; value: number; onChange: (value: string) => void }) {
  return <label className="impact-field"><span>{label}</span><small>{help}</small><input type={locale === "fa" ? "text" : "number"} inputMode="numeric" min="0" value={locale === "fa" ? numberText(value, locale) : value} onChange={(event) => onChange(event.target.value)} /></label>;
}

function ImpactBar({ locale, label, value, total }: { locale: Locale; label: string; value: number; total: number }) {
  const width = total > 0 ? Math.max(3, (value / total) * 100) : 3;
  return <div className="impact-bar-row"><div className="impact-bar-label"><span>{label}</span><strong>{locale === "fa" ? "ریال" : "$"} {money(value, locale)}</strong></div><div className="impact-bar"><span style={{ width: `${width}%` }} /></div></div>;
}

function Overview({ copy, result, locale }: { copy: Copy; result: { investment: number; total: number; ratio: number; values: { social: number; environmental: number; economic: number } }; locale: Locale }) {
  return <div className="impact-chart"><h3>{copy.chartTitle}</h3><div className="impact-bars"><ImpactBar locale={locale} label={copy.social} value={result.values.social} total={result.total} /><ImpactBar locale={locale} label={copy.environmental} value={result.values.environmental} total={result.total} /><ImpactBar locale={locale} label={copy.economic} value={result.values.economic} total={result.total} /></div></div>;
}
